./target/debug/conduit-cli start > "$app_log" 2>&1 &
app_pid=$!
for _ in {1..60}; do
  if curl -fsS "http://localhost:$PORT/_health" >/dev/null 2>&1; then break; fi
  if ! kill -0 "$app_pid" 2>/dev/null; then cat "$app_log"; exit 1; fi
  sleep 1
done
cd ..
realworld_spec/bin/run-hurl "$PORT"
cd conduit
